window.DOSIK=window.DOSIK||{};DOSIK["sg_civ"]={"1":[{"t":"vs","title":"공경비와 민간경비","cols":[{"name":"공경비","items":["일반 국민들을 위하여 관할 구역 내에서 법 집행의 권한을 가진다."]},{"name":"민간경비","items":["경비 대상이 공경비와 구별된다.","제한된 근무지역 내에서 경찰권을 일부 행사할 수 있는 민간경비원도 있다.","경찰과 민간경비는 상호보완적 관계에 있다.","영역이 뚜렷하고 확실하게 구분되는 것은 아니다."]}]},{"t":"tree","title":"경비의 개념","root":"민간경비원 지위","branches":[["비렉(A. J. Bilek)","민간경비원의 법적 지위를 크게 3가지 유형으로 구분하였다."],["형식적 개념","경비의 주체를 공적 주체와 사적 주체로 명확하게 구분한다."],["대륙법계 개념","민간경비는 국가의 지도ㆍ감독 하에 제한적인 기능만을 담당한다."],["영미법계 개념","민간경비의 업무범위가 경찰과 유사하나 집행 권한에 차이가 있다."]]},{"t":"vs","title":"자체경비와 계약경비","cols":[{"name":"자체경비","items":["계약경비보다 자신을 고용한 회사나","고용주에 대한 충성도가 상대적으로 높다.","계약경비보다 결원의 보충 및 추가인력의 배치가 상대적으로 어렵다."]},{"name":"계약경비","items":["자체경비보다 상대적으로 전문성이 높다."]}]}],"2":[{"t":"flow","title":"고대의 경비","steps":["원시시대의 대표적인 경비 형태는 절벽 동굴이나 수상가옥 등 주거지를 이용한 방법 이다.","함무라비 시대에는 정부가 법 집행을 할 수 있고 개인에게 책임을 부여할 수 있었다.","고대 로마 시대에는 지배자가 통치하는 군대가 운영되었으며, 이들은 최초의 비무장 수도경찰로 간주된다."]},{"t":"table","title":"각국의 민간경비","head":["나라","내용"],"rows":[["미국","일부 주에서는 경찰관 신분으로 민간경비회사에서 part-time job을 하기도 한다."],["일본(제도·역사)","경비업법 제정 당시에는 신고제로 운영되었다가 허가제로 변경되었다. · 제2차 세계대전 이후에 현대적 민간경비업의 출현을 맞이하게 되었다."],["일본(진출·발전)","1980년대 초 한국에 진출하였고 그 후반에는 중국에까지 진출하였다. · 시설경비ㆍ공항보안 뿐 아니라 핵연료물질 운반 등 폭 넓은 분야로 발전하였다. · 경비업계와 경찰 간의 상호 연대를 강화하는 추세이다."],["한국","용역경비업법이 경비업법으로 변경됨으로써 포괄적인 개념의 전문경비제도를 도입하는 계기가 되었다. · 1980년대 이후 기계경비시스템이 점차적으로 도입되었다. · 경비협회의 업무는 경비업법에 규정되어 있다."]]}],"3":[{"t":"tree","title":"민간경비의 현실","root":"민간경비산업 현황","branches":[["경찰","일선 치안현장의 경찰인력이 부족하다. · 경찰의 민생 치안부서에 대한 기피 현상이 있다. · 최첨단 CCTV 등 과학치안의 필요성이 있다."],["교육·업종","민간경비원의 교육과정이 현실과 맞지 않는다는 지적이 있다. · 기계경비보다 인력경비에 치중되어 있는 현실이다. · 경비업체들이 활동할 수 있는 업종이 일본에 비해 제한되어 있다."]]},{"t":"table","title":"범죄 환경의 변화","head":["원인","범죄"],"rows":[["국제화ㆍ개방화","내국인의 해외범죄, 외국인의 국내범죄가 증가하고 있다."],["인터넷 등 컴퓨터통신망의 발달","해킹 등 첨단사이버범죄가 대폭 증가하고 있다."],["청소년","마약범죄 증가가 사회문제로 대두되었다."],["인구의 고령화","노인범죄 및 노인대상범죄가 증가하고 있다."],["다문화 사회·인구구조 글로벌화","외국인 근로자 및 불법체류자 등에 의한 범죄 가 증가하고 있다."],["정보화사회의 발전","첨단범죄의 증가로 이에 대응하는 민간경비의 전문성이 요 구될 것이다."]]}],"4":[{"t":"vs","title":"민간경비원의 법적 지위","cols":[{"name":"할 수 있는 것","items":["법적 지위는 일반시민과 같은 사인(私人)에 불과하다.","자구행위를 할 수 있다.","현행범을 체포할 수 있다.","정당방위나 긴급피난은 위법성이 조각된다.","수집한 증거가 법정에서 원용될 경우 증거능력이 인정된다."]},{"name":"할 수 없는 것","items":["범죄에 대한 수사권을 행사할 수 없다."]}]},{"t":"table","title":"신임교육","head":["구분","교육"],"rows":[["일반경비원","24시간의 신임교육"],["특수경비원","80시간의 신임교육"],["청원경찰","임용된 사람은 2주간 76시간의 교육"]]},{"t":"table","title":"자격증제도와 직무","head":["항목","내용"],"rows":[["경비지도사","소방기관과의 연락방법에 대한 지도는 경비지도사의 직무이다."],["미국","대다수 주에서 민간경비 서비스에 대한 자격증제도를 두고 있으며 점차 증가 추세에 있다."],["일본","6개 경비업무 영역에 걸쳐 자격증제도를 운영하고 있다."]]}],"5":[{"t":"cause","title":"통솔범위의 원리","causes":["한 사람의 상관이 효과적으로 감독할 수 있는 부하직원의 수","계층의 수가 적으면 통솔범위가 넓어지는 경향이 있다.","상급자의 통솔범위는 부하의 자질이 높을수록 넓다.","여러 장소에 근무하는 경비원을 통솔하는 것보다 한 곳에 근무하는 경비원을 통솔하는 것이 통솔범위가 넓다."],"result":"통솔범위가 넓어짐","effects":[]},{"t":"tree","title":"명령 계통","root":"명령 계통의 효과","branches":[["책임소재","업무의 책임소재를 분명하게 할 수 있다."],["부하","부하가 조직적이고, 책임감 있게 일할 수 있다."],["조직의 장","조직의 장으로 하여금 전체적인 조정을 가능하게 한다."],["보고","경비원은 자신을 직접 관리하고 있는 경비책임자로부터 지시를 받아야 하고, 항상 그 책임자에게 보고해야 한다."],["재량권","최고관리자는 중간관리자에게 책임의 범위 내에서 업무를 수행할 수 있도록 재량권을 부여하여야 한다."]]},{"t":"table","title":"교육훈련","head":["측면","내용"],"rows":[["교육훈련","직무수행에 필요한 지식과 기술 습득, 일반능력 개발, 가치관의 발전적 변화를 촉진하 는 계획적 활동이다."],["경영적 측면","경영전략의 전개에 필요한 인력의 확보, 기업문화의 전승을 위해 서 실시되는 것이다."],["개인적 측면","개개인이 보유한 잠재능력을 개발ㆍ육성하고, 직장생활 능력 및 사회적 능력을 향상시키는 전인교육을 지향해야 한다."]]}],"6":[{"t":"flow","title":"경비위해요소 분석단계","steps":["위해요소 인지","손실발생 예측","위해정도 평가","비용효과분석"]},{"t":"tree","title":"경비위해요소의 유형","root":"경비위해요소의 유형에는 자연적 위해, 인위적 위해, 특정한 위해가 있다.","branches":[["자연적 위해","자연현상에 의해 야기되는 자연재해이다. · 홍수, 폭풍, 지진 등이 있다."],["특정한 위해","특정 시설물 및 국가 등에 따라 성질이나 유형이 다양하게 나타나는 위해이다."]]},{"t":"def","term":"경비위해분석","text":"경비 활동의 전제가 된다. 경비위해요소를 인지하는 것은 경비대상시설이 안고 있는 경비상의 취약점을 파악하는 것이다.","ex":["효과적인 경비프로그램을 실행하기 위해서는 경비위해요소 조사와 분석이 선행되어야 한다."]},{"t":"def","term":"비용효과분석","text":"경비의 비용효과분석이란 투입비용에 대한 산출효과를 비교하여 적절한 경비수준을 결정하는 과정이다."},{"t":"tree","title":"경비계획","root":"경비계획","branches":[["환경","물리적 환경을 개선하여 범죄를 억제하고 주민의 불안감을 해소하고자 하는 이론이다."],["잠금장치","건물에는 정교하면서도 파손되기 어려운 잠금장치를 설치해야 한다."],["참여","경비계획 과정에는 관련 분야나 계층의 충분한 참여가 이루어져야 한다."]]}],"7":[{"t":"tree","title":"출입문과 창문","root":"출입문과 창문","branches":[["구조","창문과 출입문 등과 같이 경계구역과 연결되어 있는 문은 튼튼한 구조물로 이루어져야 한다."],["긴급 출입문","긴급목적을 위해 만들어진 출입문은 외부의 침입으로부터 열리지 않도록 특별한 장치를 갖추고 있어야 한다."],["비상구","창문과 출입문은 화재나 여러 가지 위험한 사고의 발생에 대비하여 비상구 등 예비적 조치가 사전에 충분히 마련되어야 한다."],["구분","출입문은 정문과 후문의 주 용도를 구분하는 것이 좋다. · 상품판매시설의 경우 직원용 출입구와 고객용 출입구를 구분하는 것이 좋다."],["차량출입구","여러 종류의 차량 통행이 이루어지기 때문에 충분히 넓어야 한다."]]},{"t":"tree","title":"보안조명","root":"보안조명","branches":[["설치","경계구역의 안과 밖을 비출 수 있도록 적당한 밝기와 높이에 설치한다."],["위치","조명시설의 위치가 경비원의 시야를 방해해서는 안 되며, 가능한 그림자가 생기지 않도록 설치해야 한다."],["역할","경비조명은 침입자의 침입의도를 사전에 포기하도록 하는 심리적 압박과 건물의 미적 감각을 살려주는 역할을 한다."]]},{"t":"vs","title":"장벽","cols":[{"name":"자연적 장벽","items":["강, 계곡, 암벽 등"]},{"name":"인공적 장벽","items":["울타리, 도로상의 방책, 초소ㆍ망루 등","콘서티나 철사는 철조망 설치 및 제거가 용이하여 이동성이 뛰어난 철조망이다."]}]}],"8":[{"t":"vs","title":"기계경비","cols":[{"name":"장점","items":["외부 침입을 정확하게 탐지하고 신속하게 대응할 수 있다.","장기적으로 경비 소요비용의 절감효과를 가져온다.","장기적으로 운영비용의 절감효과를 기대할 수 있다."]},{"name":"단점","items":["오경보의 문제가 있을 수 있다.","너무 맹신하면 범죄자에게 역이용 당할 가능성이 있다.","경찰관서에 직접 연결하는 기계경비 시스템에 대해 경찰이 거부감을 가질 수 있다.","유지보수에 전문 인력이 요구된다."]}]},{"t":"def","term":"호송경비","text":"운반 중에 있는 현금ㆍ유가증권ㆍ귀금속ㆍ상품 그 밖의 물건에 대하여 도난ㆍ화재 등 위험발생을 방지하는 업무를 의미한다."},{"t":"def","term":"혼잡경비","text":"각종 행사를 위해 모인 불특정 군중에 의해 발생되는 혼란 상태를 사전에 예방ㆍ경계하고, 위험한 사태가 발생한 경우에 신속하게 조치해 확대를 방지하는 경 비활동이다.","ex":["일본은 경비업법 제2조 2호 업무에 혼잡경비를 규정하고 있다.","한국은 시설경비업무 등을 통하여 혼잡경비업무를 수행하고 있다."]}],"9":[{"t":"tree","title":"피난 유도","root":"피난 유도","branches":[["안전 확보","상황에 따라 필요시 보호 우선순위에 의한 안전을 확보한다."],["출입구","탈출 시 발생하는 혼란상황을 방지하기 위해 출입구와 비상구를 확실하게 장악하고 통제한다."],["질서","인파가 무질서한 경우가 많으므로 적절한 안내와 통솔을 통하여 질서를 도모한다."],["다수 피난자","피난자가 다수인 경우에는 사람들을 분산하여 혼란을 방지하고 위험장소에 있는 자가 조기에 피난할 수 있도록 한다."],["엘리베이터","초고층 빌딩 등 특수한 경우를 제외하고 엘리베이터는 사용하지 않는다."],["현장보존","현장보존의 범위에 있는 모든 사람을 신속히 퇴장시킨다."]]},{"t":"flow","title":"화재층 피난 순서","steps":["화재층","상층","하층"]},{"t":"table","title":"재난별 대피","head":["재난","대피"],"rows":[["지진","발생 시 가스밸브를 잠그고 건물 밖 공터 등으로 대피한다."],["엘리베이터 안 지진","모든 층을 누르고 가장 먼저 정지하는 층에 내려서 대피한다."],["화재","대피 시에는 수건 등을 물에 적셔서 입과 코를 막고 낮은 자세로 대피한다."]]}],"10":[{"t":"tree","title":"정보시스템 보안","root":"정보시스템 보안","branches":[["재평가","정보시스템의 보안은 주기적으로 재평가되어야 한다."],["권리 존중","정보시스템의 보안은 타인의 권리와 합법적 이익이 존중될 수 있도록 운영되어야 한다."],["가용성","정보와 정보시스템의 사용을 허가 받은 사람이 이를 사용하려고 할 때는 언제든지 이를 사용할 수 있도록 보장하는 것을 의미한다."],["패스워드","권한 없는 사람이 해독할 수 없도록 관리한다."],["파일","극비의 자료가 수록된 파일이나 중요 프로그램이 수록된 파일에는 레이블링 (Labeling)에 의해 관리한다."],["문서","업무흐름과 프로그램의 내용이 불일치하지 않도록 문서기록화를 철저히 한다."]]},{"t":"def","term":"융합보안","text":"물리보안요소와 정보보안요소를 통합해 효율성을 높이는 활동이다.","ex":["통합인증제(Single Sign On)가 융합보안의 대표적 사례이다.","물리보안시스템의 IT화에 따른 원가절감이 요구됨에 따라 중요성이 부각되고 있다."]},{"t":"table","title":"융합보안 관리","head":["대상","관리"],"rows":[["보안영역","물리적 보안영역, 관리적 보안영역, 기술적 보안영역을 통합적으로 관리한다."],["보안인증","물리적 보안인증과 사이버 보안인증을 통합적으로 관리하여 보안관리를 강화한다."],["데이터","개인, 기업, 정부단체 등의 데이터를 통합해 정확한 사고징후를 감지하고 총체적으로 대응할 수 있다."]]}]};
